import csv, glob, os
files = ['SPX','NDX','SOX','BTC','ETH','XAU','WTI','COPPER','US10Y','CN10Y','HSI','N225','SX5E','000300.SH','000688.SH']
def load(fn):
    rows = []
    with open(fn) as f:
        r = csv.DictReader(f)
        for row in r:
            rows.append(row)
    return rows
for s in files:
    fn = f'../persistent/stock_data/{s}.csv'
    rows = load(fn)
    # get last ~70 closes
    closes = []
    for row in rows[-70:]:
        try:
            closes.append(float(row['close']))
        except:
            pass
    if len(closes) < 2: 
        print(s, "too few"); continue
    last = closes[-1]
    def ret(n):
        return (last/closes[-1-n]-1)*100 if len(closes)>n else float('nan')
    import statistics
    def vol(n):
        if len(closes)<=n+1: return float('nan')
        rets = [(closes[i]/closes[i-1]-1) for i in range(len(closes)-n, len(closes))]
        return statistics.pstdev(rets)*(252**0.5)*100
    print(f"{s:10s} last={last:12.2f} r5d={ret(5):+6.2f}% r20d={ret(20):+7.2f}% r60d={ret(60):+8.2f}% vol20={vol(20):5.1f}%")
