import json, zlib, base64, io, pandas as pd, numpy as np

def load_signal(fid, cutoff):
    with open(f'factors/{fid}.json') as fh:
        d = json.load(fh)
    art = d['validation']['signal_artifact']
    csv = zlib.decompress(base64.b64decode(art['data'])).decode()
    df = pd.read_csv(io.StringIO(csv), parse_dates=[0])
    df = df.set_index(df.columns[0])
    df = df[df.index <= cutoff]
    return df

cutoff = pd.Timestamp('2026-11-18')
fids = ['beta_vix_60d_neg','vol_of_vol20x60','low_vol_20d','mom_120d_skip5','beta_cn10y_60d','down_vol_ratio_20x120','mom_10d_skip5','vix_beta_cond_60x20']
panels = {}
for f in fids:
    panels[f] = load_signal(f, cutoff)
    print(f, panels[f].shape, panels[f].index.min().date(), '->', panels[f].index.max().date())

def rank_ic_series(fa, fb):
    a = panels[fa].rank(axis=1); b = panels[fb].rank(axis=1)
    idx = a.index.intersection(b.index)
    out = []
    for t in idx:
        x = a.loc[t].values; y = b.loc[t].values
        m = ~(np.isnan(x)|np.isnan(y))
        if m.sum() >= 8:
            out.append(np.corrcoef(x[m], y[m])[0,1])
    return np.array(out)

names = fids
