import csv, glob, os
import statistics
names = sorted([os.path.basename(f).replace('.csv','') for f in glob.glob('../persistent/stock_data/*.csv')])
print('asset        last_close    r5d     r20d    r60d    vol20d   vol60d  trend20d')
for n in names:
    rows = list(csv.reader(open(f'../persistent/stock_data/{n}.csv')))
    hdr = rows[0]
    # find columns
    di = hdr.index('date'); ci = hdr.index('close')
    data = []
    for r in rows[1:]:
        if r and r[di] <= '2028-09-06':
            try: data.append((r[di], float(r[ci])))
            except: pass
    closes = [c for _,c in data]
    if len(closes) < 65: 
        print(f'{n:12s} insufficient ({len(closes)})'); continue
    c = closes[-1]
    def ret(k): return closes[-1]/closes[-1-k]-1 if closes[-1-k] else float('nan')
    def vol(k):
        rs = [closes[i]/closes[i-1]-1 for i in range(len(closes)-k, len(closes))]
        return statistics.pstdev(rs)*(252**0.5)
    ma20 = sum(closes[-20:])/20
    print(f'{n:12s} {c:10.2f} {ret(5)*100:6.2f}% {ret(20)*100:7.2f}% {ret(60)*100:7.2f}% {vol(20)*100:6.1f}% {vol(60)*100:6.1f}% {(c/ma20-1)*100:6.2f}%')
"

