import json, base64, zlib, io, csv
def try_decode(f):
    d = json.load(open(f))
    art = d['validation']['signal_artifact']
    if not isinstance(art, dict) or 'data' not in art:
        return 'NO ARTIFACT FIELD'
    enc = art['data']
    try:
        raw = base64.b64decode(enc)
        dec = zlib.decompress(raw)
        txt = dec.decode('utf-8')
        rows = txt.strip().split('\n')
        ncols = len(rows[0].split(',')) if rows else 0
        return 'OK rows=%d cols=%d bytes=%d' % (len(rows), ncols, len(dec))
    except Exception as e:
        return 'DECODE FAIL: %r' % e
