import json, numpy as np, pandas as pd

fids = ['beta_vix_60d_neg','mom_120d_skip5','sign_ewma_60d','vol_beta_spx_60d','mom_10d_skip5','down_vol_ratio_20x120','skew_20d_neg']
ser = {}
for fid in fids:
    d = json.load(open(f'factors/{fid}.json'))
    sa = d.get('signal_artifact', {})
    if sa.get('data') is not None:
        data = sa['data']
        if isinstance(data, list):
            arr = np.array(data, dtype=float)
            ser[fid] = arr
        else:
            print(fid, 'data type', type(data))
    else:
        # maybe artifact stored elsewhere
        print(fid, 'no signal_artifact data')

if ser:
    # cross-sectional rank correlation of the most recent valid row
    rows = []
    for fid in fids:
        if fid in ser:
            arr = ser[fid]
            # find last row with all valid values
            for i in range(arr.shape[0]-1, -1, -1):
                row = arr[i]
                if np.isfinite(row).all():
                    rows.append((fid, row))
                    break
    print('\nMost recent cross-sectional signals:')
    names = ['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
    for fid, row in rows:
        print(fid, np.round(row,3))
    # pairwise rank corr of last 20 valid rows
    print('\nPairwise avg cross-sectional rank corr (last 20d):')
    fids_present = [f for f in fids if f in ser]
    m = len(fids_present)
    n = 20
    corrs = np.zeros((m,m))
    for a in range(m):
        for b in range(a+1,m):
            cs = []
            A, B = ser[fids_present[a]], ser[fids_present[b]]
            for i in range(max(0,min(A.shape[0],B.shape[0])-n), min(A.shape[0],B.shape[0])):
                ra = pd.Series(A[i]).rank().values
                rb = pd.Series(B[i]).rank().values
                if np.isfinite(ra).all() and np.isfinite(rb).all():
                    cs.append(np.corrcoef(ra, rb)[0,1])
            corrs[a,b] = np.nanmean(cs) if cs else np.nan
            print(f'{fids_present[a]} vs {fids_present[b]}: {corrs[a,b]:.2f}')
